            answer = (answer + fastPower(e - o, total, mod)) % mod;
            long invTwo = fastPower(2, mod - 2, mod);
            answer = (answer * invTwo) % mod;
            System.out.println(answer);
        }
        sc.close();
    }

    static long fastPower(long base, long exp, int mod) {
        long res = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return res;
    }
}
