#include <iostream>
#include <cstdint>

using namespace std;

long long fastPower(long long base, long long exp, int mod) {
    long long res = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            res = (res * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
    cin >> n >> m >> l >> r;
    long long total = (long long)n * m;
    int mod = 998244353;
    if (total % 2 != 0) {
        long long result = fastPower(r - l + 1, total, mod);
        cout << result << "\n";
    } else {
        int k = r - l + 1;
        int e = r / 2 - l / 2;
        if (l % 2 == 0) e++;
        int o = k - e;
        long long answer = fastPower(e + o, total, mod);
        answer = (answer + fastPower(e - o, total, mod)) % mod;
        long long invTwo = fastPower(2, mod - 2, mod);
        answer = (answer * invTwo) % mod;
        cout << answer << "\n";
    }
    return 0;
}
